html:
{%- set c = get_id_card_data(doc.name) -%}
<style>
	.psl-cards { font-family: "Poppins", "Helvetica Neue", Arial, sans-serif; }
	.psl-cards * { box-sizing: border-box; }
	.psl-sheet td.psl-gap { width: 8mm; }
	.psl-card {
		width: 85.6mm; height: 54mm; border-radius: 3.2mm; overflow: hidden; position: relative;
		border: 0.2mm dashed #c9cfdb; background: #ffffff; color: #0f1b4c;
	}
	.psl-band {
		height: 13mm; padding: 0 3.5mm; color: #fff;
		background: #1e3cf4;
		background: -webkit-linear-gradient(left, #1e3cf4 0%, #3c6df5 60%, #6ccab7 100%);
		background: linear-gradient(90deg, #1e3cf4 0%, #3c6df5 60%, #6ccab7 100%);
	}
	.psl-band table { width: 100%; height: 13mm; border-collapse: collapse; }
	.psl-band td { vertical-align: middle; padding: 0; }
	.psl-band .psl-logo { width: 9mm; height: 9mm; background: #fff; border-radius: 2mm; padding: 0.8mm; display: block; }
	.psl-brand { font-size: 12pt; font-weight: 700; letter-spacing: 1.2pt; line-height: 1.05; padding-left: 2mm !important; }
	.psl-brand small { display: block; font-size: 5.6pt; font-weight: 400; letter-spacing: 0.2pt; opacity: 0.92; }
	.psl-tag { text-align: right; font-size: 5.6pt; font-weight: 600; letter-spacing: 0.8pt; }
	.psl-tag span { border: 0.25mm solid rgba(255,255,255,0.8); border-radius: 3mm; padding: 0.6mm 1.8mm; }

	.psl-body { padding: 2.5mm 3.5mm 0; }
	.psl-body > table { width: 100%; border-collapse: collapse; }
	.psl-body td { vertical-align: top; padding: 0; }
	.psl-photo { width: 20mm; height: 23mm; border-radius: 2mm; object-fit: cover; display: block; border: 0.5mm solid #e6ecff; }
	.psl-initials { width: 20mm; height: 23mm; border-radius: 2mm; background: #e9efff; color: #3c6df5;
		font-size: 20pt; font-weight: 700; text-align: center; line-height: 23mm; }
	.psl-info { padding-left: 3mm !important; }
	.psl-name { font-size: 10.5pt; font-weight: 700; line-height: 1.15; margin-bottom: 1mm; color: #0f1b4c; }
	.psl-id { display: inline-block; font-size: 6.5pt; font-weight: 600; color: #1e3cf4; background: #e9efff; border-radius: 1.5mm; padding: 0.4mm 1.6mm; margin-bottom: 1.6mm; }
	.psl-row { font-size: 6.5pt; line-height: 1.55; color: #4a5680; }
	.psl-row b { color: #0f1b4c; font-weight: 600; }

	.psl-foot { position: absolute; left: 0; right: 0; bottom: 0; height: 12.5mm; background: #f3f6ff; border-top: 0.2mm solid #e3e9fb; padding: 0 3.5mm; }
	.psl-foot table { width: 100%; height: 12.5mm; border-collapse: collapse; }
	.psl-foot td { vertical-align: middle; padding: 0; font-size: 5.6pt; line-height: 1.35; color: #4a5680; }
	.psl-foot .psl-seat { font-size: 11pt; font-weight: 700; color: #1e3cf4; line-height: 1; }
	.psl-foot .psl-k { font-size: 5pt; text-transform: uppercase; letter-spacing: 0.6pt; color: #8a94b8; }
	.psl-girls { color: #d63384 !important; }

	.psl-back { padding: 0; }
	.psl-back > table { width: 100%; height: 54mm; border-collapse: collapse; }
	.psl-back td { vertical-align: middle; padding: 0; }
	.psl-qr-cell { width: 36mm; text-align: center; background: #f3f6ff; border-right: 0.2mm solid #e3e9fb; }
	.psl-qr { width: 30mm; height: 30mm; display: block; margin: 0 auto 1.2mm; image-rendering: pixelated; }
	.psl-qr-hint { font-size: 5.6pt; color: #4a5680; font-weight: 600; }
	.psl-back-info { padding: 0 3.5mm !important; }
	.psl-back-title { font-size: 8pt; font-weight: 700; color: #1e3cf4; margin-bottom: 1.6mm; letter-spacing: 0.6pt; }
	.psl-back-row { font-size: 6.3pt; color: #4a5680; line-height: 1.6; }
	.psl-back-row b { color: #0f1b4c; }
	.psl-rules { margin-top: 2mm; padding-top: 1.6mm; border-top: 0.2mm solid #e3e9fb; font-size: 5.3pt; color: #6b7699; line-height: 1.5; }
	.psl-stripe { height: 1.4mm; background: #adfc54; background: -webkit-linear-gradient(left, #3c6df5, #6ccab7, #adfc54); background: linear-gradient(90deg, #3c6df5, #6ccab7, #adfc54); position: absolute; left: 0; right: 0; bottom: 0; }

	.psl-cut { font-size: 7pt; color: #8a94b8; margin: 0 0 2mm; }
	@media print { .psl-card { border-color: #dfe3ea; } }
</style>

<div class="psl-cards">
	<p class="psl-cut">✂ {{ _("Cut along the dashed lines. Front and back are standard ID-card size (85.6 × 54 mm).") }}</p>
	<table class="psl-sheet" style="border-collapse: collapse;"><tr>
	<td>
	<!-- FRONT -->
	<div class="psl-card">
		<div class="psl-band"><table><tr>
			<td style="width: 10mm;"><img class="psl-logo" src="{{ c.logo }}"></td>
			<td class="psl-brand">PATHSHALA<small>Library and Self Study Centre</small></td>
			<td class="psl-tag"><span>{{ _("STUDENT") }}</span></td>
		</tr></table></div>

		<div class="psl-body"><table><tr>
			<td style="width: 20mm;">
				{%- if c.photo -%}<img class="psl-photo" src="{{ c.photo }}">
				{%- else -%}<div class="psl-initials">{{ c.initials }}</div>{%- endif -%}
			</td>
			<td class="psl-info">
				<div class="psl-name">{{ doc.full_name }}</div>
				<div class="psl-id">{{ doc.name }}</div>
				<div class="psl-row">{{ _("Mobile") }}: <b>{{ doc.mobile }}</b></div>
				{%- if doc.preparing_for %}<div class="psl-row">{{ _("Preparing for") }}: <b>{{ doc.preparing_for }}</b></div>{% endif -%}
				{%- if c.branch %}<div class="psl-row">{{ _("Branch") }}: <b>{{ c.branch }}</b></div>{% endif -%}
			</td>
		</tr></table></div>

		<div class="psl-foot"><table><tr>
			<td style="width: 22%;">
				<div class="psl-k">{{ _("Seat") }}</div>
				<div class="psl-seat">{{ c.seat or "—" }}</div>
			</td>
			<td style="width: 50%;">
				<div class="psl-k">{{ _("Zone / Slot") }}</div>
				<div class="{{ 'psl-girls' if c.girls_only else '' }}"><b>{{ c.zone or _("Not assigned") }}</b></div>
				<div>{{ c.slot or "" }}</div>
			</td>
			<td style="width: 28%; text-align: right;">
				<div class="psl-k">{{ _("Valid till") }}</div>
				<div><b>{{ frappe.format(c.valid_till, {"fieldtype": "Date"}) if c.valid_till else "—" }}</b></div>
				{%- if c.locker %}<div>{{ _("Locker") }} <b>{{ c.locker }}</b></div>{% endif -%}
			</td>
		</tr></table></div>
	</div>
	</td>
	<td class="psl-gap"></td>
	<td>
	<!-- BACK -->
	<div class="psl-card psl-back">
		<table><tr>
			<td class="psl-qr-cell">
				{%- if c.qr %}<img class="psl-qr" src="{{ c.qr }}">{% endif -%}
				<div class="psl-qr-hint">{{ _("Scan at the kiosk") }}<br>{{ _("to check in / out") }}</div>
			</td>
			<td class="psl-back-info">
				<div class="psl-back-title">{{ _("MEMBER CARD") }}</div>
				{%- if doc.guardian_name or doc.guardian_mobile %}
				<div class="psl-back-row">{{ _("Guardian") }}: <b>{{ doc.guardian_name or "" }}</b>{% if doc.guardian_mobile %} · {{ doc.guardian_mobile }}{% endif %}</div>
				{%- endif %}
				<div class="psl-back-row">{{ _("No phone? Use your mobile number + PIN at the kiosk.") }}</div>
				<div class="psl-rules">
					• {{ _("This card is personal and non-transferable.") }}<br>
					• {{ _("Please maintain silence in study zones.") }}<br>
					• {{ _("If found, please return to Pathshala.") }}
				</div>
			</td>
		</tr></table>
		<div class="psl-stripe"></div>
	</div>
	</td>
	</tr></table>
</div>
